par.imgWidth  = par.texWidth;                     // align image dims to texture dims for consistency
par.imgHeight = par.texHeight;
par.enableMip = (int)(rndC & 1u);                 // enable/disable mipmaps
par.filterMode   = (int)(rndA % 3);               // small range of modes
par.boundaryMode = (int)(rndB % 3);
par.texConst     = (int)(rndC & 1u);

