int maxDim = par.texWidth;
if (par.texHeight > maxDim) maxDim = par.texHeight;
if (par.texDepth  > maxDim) maxDim = par.texDepth;
int levels = 1; // include base level 0
int cur = maxDim;
while (cur > 1 && levels < kMaxLevels) { cur = (cur + 1) / 2; ++levels; }

